"""Stateful streaming dedupe fixture."""

from __future__ import annotations

from copy import deepcopy
from typing import Dict, Any


_NEG_INF = float("-inf")


class WatermarkDeduper:
    """Deduplicate events by event_id with watermark, late-drop, and TTL eviction."""

    def __init__(self, *, allowed_lateness: int = 0, ttl: int = 100) -> None:
        if not isinstance(allowed_lateness, int) or isinstance(allowed_lateness, bool):
            raise ValueError("allowed_lateness must be an integer")
        if not isinstance(ttl, int) or isinstance(ttl, bool):
            raise ValueError("ttl must be an integer")
        if allowed_lateness < 0:
            raise ValueError("allowed_lateness must be >= 0")
        if ttl < 1:
            raise ValueError("ttl must be >= 1")
        self.allowed_lateness = allowed_lateness
        self.ttl = ttl
        # Maps event_id -> last event_time seen (for TTL eviction)
        self._seen: Dict[str, int] = {}
        # Current watermark (can be -inf initially)
        self._watermark: float = _NEG_INF

    def _validate_event(self, event: dict) -> None:
        event_id = event.get("event_id")
        event_time = event.get("event_time")
        if not isinstance(event_id, str):
            raise ValueError("event_id must be a string")
        if not isinstance(event_time, int) or isinstance(event_time, bool):
            raise ValueError("event_time must be an integer")

    def _evict(self) -> None:
        """Evict event IDs whose last seen time <= watermark - ttl."""
        if self._watermark == _NEG_INF:
            return
        evict_threshold = self._watermark - self.ttl
        to_evict = [eid for eid, t in self._seen.items() if t <= evict_threshold]
        for eid in to_evict:
            del self._seen[eid]

    def process(self, events: list[dict[str, object]]) -> list[dict[str, object]]:
        emitted: list[dict[str, object]] = []
        for event in events:
            self._validate_event(event)
            event_id = event["event_id"]
            event_time = event["event_time"]

            # Check if event is late: event_time <= watermark means late
            if self._watermark != _NEG_INF and event_time <= self._watermark:
                # Late event: drop without changing state
                continue

            # Check for duplicate
            if event_id in self._seen:
                # Update last seen time but don't emit
                # Actually per spec: "its event_id has not already been seen in retained state"
                # We still need to update the last seen time? 
                # Re-reading spec: duplicate => not emitted. State update is not specified for dups.
                # Let's update the last seen time to extend TTL for this id.
                self._seen[event_id] = max(self._seen[event_id], event_time)
                # Advance watermark still? No — only non-late events advance watermark,
                # and duplicate events that are non-late should still advance watermark.
                # Advance watermark
                new_wm = event_time - self.allowed_lateness
                if self._watermark == _NEG_INF or new_wm > self._watermark:
                    self._watermark = new_wm
                    self._evict()
                continue

            # Non-late, non-duplicate: emit
            self._seen[event_id] = event_time
            emitted.append(deepcopy(event))

            # Advance watermark
            new_wm = event_time - self.allowed_lateness
            if self._watermark == _NEG_INF or new_wm > self._watermark:
                self._watermark = new_wm
                self._evict()

        return emitted

    def snapshot(self) -> dict[str, object]:
        return {
            "allowed_lateness": self.allowed_lateness,
            "ttl": self.ttl,
            "watermark": self._watermark,
            "seen": deepcopy(self._seen),
        }

    def restore(self, snapshot: dict[str, object]) -> None:
        self.allowed_lateness = int(snapshot["allowed_lateness"])
        self.ttl = int(snapshot["ttl"])
        wm = snapshot["watermark"]
        if wm == _NEG_INF or wm == float("-inf"):
            self._watermark = _NEG_INF
        else:
            self._watermark = float(wm)
        self._seen = {str(k): int(v) for k, v in snapshot["seen"].items()}

    def state_size(self) -> int:
        return len(self._seen)
